void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class E,class F>void rejects(F&& action,const char* message){try{action();}catch(const E&){return;}throw std::runtime_error(message);}
agentflow::SecretBytes secret(const std::string& value){return agentflow::SecretBytes({reinterpret_cast<const std::uint8_t*>(value.data()),value.size()});}
bool equals(const agentflow::SecretBytes& value,const std::string& expected){const auto bytes=value.view();return bytes.size()==expected.size()&&std::equal(bytes.begin(),bytes.end(),reinterpret_cast<const std::uint8_t*>(expected.data()));}
struct Directory {std::filesystem::path path;Directory(){std::random_device random;path=std::filesystem::temp_directory_path()/std::filesystem::path("xmind-a2a-registry-"+std::to_string(random())+"-"+std::to_string(random()));if(!std::filesystem::create_directory(path))throw std::runtime_error("Cannot create A2A registry fixture directory");}~Directory(){std::error_code ignored;std::filesystem::remove_all(path,ignored);}};
void start_run(agentflow::PersistenceService& persistence,const std::string& run){persistence.create_session(run+"-session","A2A runtime contract").get();persistence.start_prompt_run(run,run+"-session",R"({"content":"actual remote delegation contract"})").get();persistence.transition(run,agentflow::RunState::queued,agentflow::RunState::running).get();}
agentflow::Operation approval(agentflow::PersistenceService& persistence,const std::string& id){const auto until=std::chrono::steady_clock::now()+std::chrono::seconds(5);while(std::chrono::steady_clock::now()<until){try{auto value=persistence.operation(id).get();if(value.state==agentflow::OperationState::awaiting_approval)return value;}catch(const agentflow::NotFound&){}std::this_thread::sleep_for(std::chrono::milliseconds(5));}throw std::runtime_error("A2A task did not publish its approval proposal");}
// A failed invocation can finish before publishing approval. Join before reading
// its captured exception, preserving the actual cause and avoiding a data race.
agentflow::Operation approval(agentflow::PersistenceService& persistence,const std::string& id,std::jthread& worker,const std::exception_ptr& failure){
    try{return approval(persistence,id);}catch(...){worker.join();if(failure)std::rethrow_exception(failure);throw;}
}
